actions.action:
// Limit interest deduction to 30% of ATI
// Excess carried forward (not implemented in Phase 1)
result.interest_expense = 0.30 * result.taxable_income;

// Limit charitable contributions to 10% of taxable income
// Excess carried forward 5 years (not implemented in Phase 1)
result.charitable_contributions = 0.10 * result.taxable_income;

// Total payments includes estimated payments + prior year overpayment credits
result.total_payments = result.estimated_tax_payments + result.total_credits;

// Refund (positive) or owed (negative)
result.refund_or_owed = result.total_payments - result.federal_tax;

// R&D credit calculation (simplified for Phase 2)
// Full implementation requires base period calculations
// Phase 2: Accept pre-calculated credit amount

// Sum all business credits
result.general_business_credit =
  result.research_development_credit +
  result.work_opportunity_credit;

// Apply to total credits
result.total_credits = result.general_business_credit;

// Asset class already specified, set recovery period
if (asset.asset_class == '3-year') {
  asset.recovery_period = 3;
  asset.depreciation_method = 'MACRS-200DB';
} else if (asset.asset_class == '5-year') {
  asset.recovery_period = 5;
  asset.depreciation_method = 'MACRS-200DB';
} else if (asset.asset_class == '7-year') {
  asset.recovery_period = 7;
  asset.depreciation_method = 'MACRS-200DB';
} else if (asset.asset_class == '10-year') {
  asset.recovery_period = 10;
  asset.depreciation_method = 'MACRS-200DB';
} else if (asset.asset_class == '15-year') {
  asset.recovery_period = 15;
  asset.depreciation_method = 'MACRS-150DB';
} else if (asset.asset_class == '20-year') {
  asset.recovery_period = 20;
  asset.depreciation_method = 'MACRS-150DB';
} else if (asset.asset_class == '27.5-year') {
  asset.recovery_period = 27.5;
  asset.depreciation_method = 'MACRS-SL';
} else if (asset.asset_class == '39-year') {
  asset.recovery_period = 39;
  asset.depreciation_method = 'MACRS-SL';
}

// Default to 7-year property if not specified
asset.asset_class = '7-year';
asset.recovery_period = 7;
asset.depreciation_method = 'MACRS-200DB';

// Calculate available Section 179 deduction
double remaining_limit = result.section_179_limit - result.section_179_total;
double section_179_amount = Math.min(asset.cost_basis, remaining_limit);

// Apply Section 179 deduction
asset.section_179_deduction = section_179_amount;
result.section_179_total += section_179_amount;

// Reduce basis for remaining depreciation
asset.cost_basis -= section_179_amount;

// Calculate bonus depreciation
double bonus_amount = asset.cost_basis * result.bonus_depreciation_rate;

// Apply bonus depreciation
asset.bonus_depreciation = bonus_amount;
result.bonus_depreciation_total += bonus_amount;

// Reduce basis for MACRS depreciation
asset.cost_basis -= bonus_amount;

// Calculate first-year MACRS depreciation using half-year convention
double macrs_rate = 0.0;

// Lookup MACRS percentage (simplified - using approximate rates)
if (asset.recovery_period == 3) {
  macrs_rate = 0.3333; // 33.33% first year (200DB, half-year)
} else if (asset.recovery_period == 5) {
  macrs_rate = 0.2000; // 20.00% first year (200DB, half-year)
} else if (asset.recovery_period == 7) {
  macrs_rate = 0.1429; // 14.29% first year (200DB, half-year)
} else if (asset.recovery_period == 10) {
  macrs_rate = 0.1000; // 10.00% first year (200DB, half-year)
} else if (asset.recovery_period == 15) {
  macrs_rate = 0.0500; // 5.00% first year (150DB, half-year)
} else if (asset.recovery_period == 20) {
  macrs_rate = 0.0375; // 3.75% first year (150DB, half-year)
} else if (asset.recovery_period == 27.5) {
  macrs_rate = 0.0182; // 1.82% first year (SL, mid-month)
} else if (asset.recovery_period == 39) {
  macrs_rate = 0.0128; // 1.28% first year (SL, mid-month)
}

// Calculate depreciation
double macrs_amount = asset.cost_basis * macrs_rate;
asset.current_year_depreciation = macrs_amount;
asset.accumulated_depreciation += macrs_amount;
result.macrs_depreciation_total += macrs_amount;

// Total depreciation = Section 179 + Bonus + MACRS
result.depreciation =
  result.section_179_total +
  result.bonus_depreciation_total +
  result.macrs_depreciation_total;

// ===== INCOME CALCULATION =====
execute(2000);  // Calculate_Net_Receipts
execute(2100);  // Calculate_Gross_Profit
execute(2600);  // Calculate_Total_Income

// ===== DEPRECIATION CALCULATION (Form 4562) =====
// Process each asset through depreciation waterfall
foreach asset in assets {
  execute(6000);  // Determine_Asset_Class
  execute(6100);  // Calculate_Section_179
  execute(6200);  // Calculate_Bonus_Depreciation
  execute(6300);  // Calculate_MACRS_Depreciation
}
execute(6900);  // Aggregate_Depreciation

// ===== DEDUCTION CALCULATION =====
execute(3000);  // Calculate_Compensation_Deduction
execute(3200);  // Calculate_Interest_Deduction (IRC 163j)
execute(3500);  // Calculate_Charitable_Contributions (10% limit)
execute(3600);  // Calculate_Total_Deductions

// ===== TAX CALCULATION =====
execute(4000);  // Calculate_Taxable_Income

// ===== NET OPERATING LOSS (NOL) =====
execute(9000);  // Calculate_Net_Operating_Loss (IRC 172)

execute(4100);  // Apply_Corporate_Tax_Rate (21%)

// ===== CREDIT CALCULATION (Form 3800) =====
execute(5100);  // Calculate_RD_Credit
execute(5300);  // Calculate_General_Business_Credit

// ===== FOREIGN TAX CREDIT (Form 1118) =====
execute(9100);  // Calculate_Foreign_Tax_Credit (IRC 901)

// ===== FINAL CALCULATION =====
execute(4300);  // Calculate_Refund_Or_Owed

// ===== SCHEDULE M-1 (Book-Tax Reconciliation) =====
execute(8000);  // Complete_Schedule_M1

// ===== SCHEDULE M-2 (Retained Earnings Analysis) =====
execute(8100);  // Complete_Schedule_M2

// ===== SCHEDULE L (Balance Sheet) =====
execute(8200);  // Complete_Schedule_L

apportionment.has_economic_nexus = false;
apportionment.apportionment_percentage = 0.0;
apportionment.state_tax = 0.0;

// Calculate average property (beginning + ending) / 2
apportionment.property_average =
  (apportionment.property_beginning_balance + apportionment.property_ending_balance) / 2.0;

// Calculate property factor
apportionment.property_factor =
  apportionment.property_average / apportionment.property_total_average;

// Calculate payroll factor
apportionment.payroll_factor =
  apportionment.payroll_in_state / apportionment.payroll_total;

// Calculate sales factor
apportionment.sales_factor =
  apportionment.sales_in_state / apportionment.sales_total;

// Three-factor formula: (P + Pa + S) / 3
apportionment.apportionment_percentage =
  (apportionment.property_factor +
   apportionment.payroll_factor +
   apportionment.sales_factor) / 3.0;

// Double-weighted sales: (P + Pa + 2×S) / 4
apportionment.apportionment_percentage =
  (apportionment.property_factor +
   apportionment.payroll_factor +
   (2.0 * apportionment.sales_factor)) / 4.0;

// Apply apportionment to federal taxable income
apportionment.apportioned_income =
  result.taxable_income * apportionment.apportionment_percentage;

// Apply state-specific adjustments
apportionment.state_taxable_income =
  apportionment.apportioned_income +
  apportionment.state_additions -
  apportionment.state_subtractions;

// Calculate state tax
apportionment.state_tax =
  apportionment.state_taxable_income * apportionment.state_tax_rate;

// Subtract state credits
apportionment.state_tax =
  Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

// Calculate refund or amount owed
apportionment.state_refund_or_owed =
  apportionment.state_payments - apportionment.state_tax;

apportionment.apportioned_income = 0.0;
apportionment.state_taxable_income = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

apportionment.apportioned_income = 0.0;
apportionment.state_taxable_income = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

// ========================================
// Schedule M-1 Line 2: Federal Tax per Books
// ========================================
// Book accounting records federal tax expense
// This is added back because federal tax is not deductible for federal tax
result.m1_federal_tax_per_books = result.federal_tax;

// ========================================
// Schedule M-1 Line 3: Excess Capital Losses
// ========================================
// Corporations can only deduct capital losses to extent of capital gains
// Any excess is not deductible (carried back/forward)
// Simplified: Assume no capital transactions for now
result.m1_excess_capital_losses = 0.0;

// ========================================
// Schedule M-1 Line 4: Income Subject to Tax NOT Recorded on Books
// ========================================
// Rare - prepaid income recognized for tax but deferred for books
result.m1_income_not_on_books = 0.0;

// ========================================
// Schedule M-1 Line 5: Expenses Recorded on Books NOT Deducted
// ========================================
double expenses_not_deducted = 0.0;

// 50% of meals and entertainment (only 50% deductible for tax)
// Book expense is 100%, tax deduction is 50%
// Addback = 50% of meals/entertainment expense
expenses_not_deducted += result.m1_meals_entertainment_50pct;

// Book-tax depreciation difference (if book > tax)
// Tax depreciation (MACRS/179/Bonus) typically exceeds book (straight-line)
// If book depreciation > tax depreciation (rare), addback the difference
// Most common: tax depreciation > book, so this is usually 0 or negative
double depreciation_addback = Math.max(0.0,
  result.m1_book_depreciation - result.depreciation);
expenses_not_deducted += depreciation_addback;

// Federal income tax (already counted in line 2, don't double-count)
// Other common items: penalties, fines, lobbying, club dues, etc.

result.m1_expenses_not_deducted = expenses_not_deducted;

// ========================================
// Schedule M-1 Line 6: Subtotal (sum of lines 1-5)
// ========================================
result.m1_subtotal =
  result.m1_net_income_per_books +
  result.m1_federal_tax_per_books +
  result.m1_excess_capital_losses +
  result.m1_income_not_on_books +
  result.m1_expenses_not_deducted;

// ========================================
// Schedule M-1 Line 7: Income on Books NOT Included on Return
// ========================================
// Tax-exempt interest (tax-exempt municipal bonds)
// On books as income, but not taxable
result.m1_income_not_on_return = result.m1_tax_exempt_interest;

// ========================================
// Schedule M-1 Line 8: Deductions on Return NOT Charged Against Books
// ========================================
double deductions_not_on_books = 0.0;

// Tax depreciation exceeding book depreciation (most common case)
// MACRS/179/Bonus typically > straight-line book depreciation
double tax_depreciation_excess = Math.max(0.0,
  result.depreciation - result.m1_book_depreciation);
deductions_not_on_books += tax_depreciation_excess;

// Capital loss carryover from prior years (deductible for tax, not on books)
deductions_not_on_books += result.m1_capital_loss_carryover;

result.m1_deductions_not_on_books = deductions_not_on_books;

// ========================================
// Schedule M-1 Line 9: Total (sum of lines 7-8)
// ========================================
result.m1_total_deductions =
  result.m1_income_not_on_return +
  result.m1_deductions_not_on_books;

// ========================================
// Schedule M-1 Line 10: Reconciled Income (line 6 - line 9)
// ========================================
// This MUST equal taxable income (Form 1120 line 28)
result.m1_reconciled_income =
  result.m1_subtotal - result.m1_total_deductions;

// Validation: Check if reconciliation matches taxable income
double reconciliation_difference =
  Math.abs(result.m1_reconciled_income - result.taxable_income);

// If difference > $1, log warning (should match exactly)
if (reconciliation_difference > 1.0) {
  // Schedule M-1 reconciliation error
  // M-1 line 10 should equal taxable income
  // Difference may indicate missing book-tax adjustments
}

// No book income provided - skip Schedule M-1
// May occur if only tax return data available
result.m1_net_income_per_books = 0.0;
result.m1_subtotal = 0.0;
result.m1_reconciled_income = result.taxable_income;

// ========================================
// Schedule M-2 Line 2: Net Income per Books
// ========================================
// Comes from Schedule M-1 line 1
result.m2_net_income_per_books = result.m1_net_income_per_books;

// ========================================
// Schedule M-2 Line 3: Other Increases
// ========================================
double other_increases = 0.0;

// Prior period adjustments (corrections to prior years)
other_increases += result.m2_prior_year_adjustments;

// Other possible increases:
// - Adjustments to beginning balance
// - Error corrections
// - Accounting changes

result.m2_other_increases = other_increases;

// ========================================
// Schedule M-2 Line 4: Total (1 + 2 + 3)
// ========================================
result.m2_total_increases =
  result.m2_beginning_balance +
  result.m2_net_income_per_books +
  result.m2_other_increases;

// ========================================
// Schedule M-2 Line 5: Distributions
// ========================================
// 5a: Cash distributions (dividends paid in cash)
// 5b: Stock distributions (stock dividends)
// 5c: Property distributions (distribution of assets)
result.m2_total_distributions =
  result.m2_cash_distributions +
  result.m2_stock_distributions +
  result.m2_property_distributions;

// ========================================
// Schedule M-2 Line 6: Other Decreases
// ========================================
double other_decreases = 0.0;

// Treasury stock purchases (reduce retained earnings)
other_decreases += result.m2_treasury_stock_adjustments;

// Other possible decreases:
// - Stock redemptions
// - Prior period adjustments (negative)
// - Legal capital transfers

result.m2_other_decreases = other_decreases;

// ========================================
// Schedule M-2 Line 7: Total (5 + 6)
// ========================================
result.m2_total_decreases =
  result.m2_total_distributions +
  result.m2_other_decreases;

// ========================================
// Schedule M-2 Line 8: Ending Balance (4 - 7)
// ========================================
result.m2_ending_balance =
  result.m2_total_increases - result.m2_total_decreases;

// Validation: Ending balance should match balance sheet
// If corporation has Schedule L (balance sheet), verify:
// M-2 line 8 = Schedule L line 25 (retained earnings - unappropriated)

// No retained earnings data - skip Schedule M-2
result.m2_beginning_balance = 0.0;
result.m2_ending_balance = 0.0;

// ========================================
// ASSETS TOTALS
// ========================================

// Calculate total assets (beginning of year)
result.l_total_assets_beg =
  result.l_cash_beg +
  (result.l_accounts_receivable_beg - result.l_bad_debt_allowance_beg) +
  result.l_inventories_beg +
  result.l_us_govt_obligations_beg +
  result.l_tax_exempt_securities_beg +
  result.l_other_current_assets_beg +
  result.l_loans_to_shareholders_beg +
  result.l_mortgage_real_estate_loans_beg +
  result.l_other_investments_beg +
  (result.l_buildings_gross_beg - result.l_accumulated_depreciation_beg) +
  (result.l_depletable_assets_beg - result.l_accumulated_depletion_beg) +
  result.l_land_beg +
  (result.l_intangible_assets_gross_beg - result.l_accumulated_amortization_beg) +
  result.l_other_assets_beg;

// Calculate total assets (end of year)
result.l_total_assets_end =
  result.l_cash_end +
  (result.l_accounts_receivable_end - result.l_bad_debt_allowance_end) +
  result.l_inventories_end +
  result.l_us_govt_obligations_end +
  result.l_tax_exempt_securities_end +
  result.l_other_current_assets_end +
  result.l_loans_to_shareholders_end +
  result.l_mortgage_real_estate_loans_end +
  result.l_other_investments_end +
  (result.l_buildings_gross_end - result.l_accumulated_depreciation_end) +
  (result.l_depletable_assets_end - result.l_accumulated_depletion_end) +
  result.l_land_end +
  (result.l_intangible_assets_gross_end - result.l_accumulated_amortization_end) +
  result.l_other_assets_end;

// ========================================
// LIABILITIES TOTALS
// ========================================

// Calculate total liabilities (beginning of year)
result.l_total_liabilities_beg =
  result.l_accounts_payable_beg +
  result.l_mortgages_notes_bonds_lt1yr_beg +
  result.l_other_current_liabilities_beg +
  result.l_loans_from_shareholders_beg +
  result.l_mortgages_notes_bonds_gte1yr_beg +
  result.l_other_liabilities_beg;

// Calculate total liabilities (end of year)
result.l_total_liabilities_end =
  result.l_accounts_payable_end +
  result.l_mortgages_notes_bonds_lt1yr_end +
  result.l_other_current_liabilities_end +
  result.l_loans_from_shareholders_end +
  result.l_mortgages_notes_bonds_gte1yr_end +
  result.l_other_liabilities_end;

// ========================================
// SHAREHOLDERS' EQUITY TOTALS
// ========================================

// Sync retained earnings unappropriated with Schedule M-2
// Schedule L line 26 (ending) should equal Schedule M-2 line 8
if (result.m2_ending_balance != 0) {
  result.l_retained_earnings_unappropriated_end = result.m2_ending_balance;
}
if (result.m2_beginning_balance != 0) {
  result.l_retained_earnings_unappropriated_beg = result.m2_beginning_balance;
}

// Calculate total shareholders' equity (beginning of year)
result.l_total_equity_beg =
  result.l_capital_stock_beg +
  result.l_additional_paid_in_capital_beg +
  result.l_retained_earnings_appropriated_beg +
  result.l_retained_earnings_unappropriated_beg +
  result.l_adjustments_to_equity_beg -
  result.l_treasury_stock_beg;

// Calculate total shareholders' equity (end of year)
result.l_total_equity_end =
  result.l_capital_stock_end +
  result.l_additional_paid_in_capital_end +
  result.l_retained_earnings_appropriated_end +
  result.l_retained_earnings_unappropriated_end +
  result.l_adjustments_to_equity_end -
  result.l_treasury_stock_end;

// ========================================
// BALANCE SHEET EQUATION VALIDATION
// ========================================

// Calculate total liabilities and equity (should equal assets)
result.l_total_liabilities_and_equity_beg =
  result.l_total_liabilities_beg + result.l_total_equity_beg;

result.l_total_liabilities_and_equity_end =
  result.l_total_liabilities_end + result.l_total_equity_end;

// Validate balance sheet equation: Assets = Liabilities + Equity
double balance_difference_beg =
  Math.abs(result.l_total_assets_beg - result.l_total_liabilities_and_equity_beg);

double balance_difference_end =
  Math.abs(result.l_total_assets_end - result.l_total_liabilities_and_equity_end);

// If difference > $1, log warning (should balance exactly)
if (balance_difference_beg > 1.0 || balance_difference_end > 1.0) {
  // Balance sheet does not balance
  // Assets must equal Liabilities + Equity
  // Check for missing or incorrect values
}

// No balance sheet data - skip Schedule L
result.l_total_assets_beg = 0.0;
result.l_total_assets_end = 0.0;
result.l_total_liabilities_and_equity_beg = 0.0;
result.l_total_liabilities_and_equity_end = 0.0;

// ========================================
// NOL Deduction with 80% Limitation
// ========================================

// Save taxable income before NOL deduction
result.taxable_income_before_nol = result.taxable_income;

// Calculate 80% limitation (IRC 172(a)(2))
// NOL deduction cannot exceed 80% of taxable income before NOL
result.nol_80pct_limitation = result.taxable_income_before_nol * 0.80;

// NOL deduction is lesser of:
// 1. NOL carryforward from prior years
// 2. 80% of taxable income before NOL
result.nol_deduction_allowed = Math.min(
  result.nol_carryforward_from_prior_years,
  result.nol_80pct_limitation
);

// Apply NOL deduction
result.taxable_income_after_nol =
  result.taxable_income_before_nol - result.nol_deduction_allowed;

// Update taxable income (replaces original calculation)
result.taxable_income = result.taxable_income_after_nol;

// Calculate remaining NOL carryforward
result.nol_carryforward_to_future_years =
  result.nol_carryforward_from_prior_years - result.nol_deduction_allowed;

// No current year NOL (profitable year)
result.nol_current_year = 0.0;

// No NOL carryforward to apply
result.taxable_income_before_nol = result.taxable_income;
result.taxable_income_after_nol = result.taxable_income;
result.nol_deduction_allowed = 0.0;
result.nol_80pct_limitation = 0.0;
result.nol_current_year = 0.0;
result.nol_carryforward_to_future_years = 0.0;

// ========================================
// Current Year NOL Generation
// ========================================

result.taxable_income_before_nol = result.taxable_income;

// Current year NOL (absolute value of negative taxable income)
result.nol_current_year = Math.abs(result.taxable_income);

// No NOL deduction this year (loss year, not profit year)
result.nol_deduction_allowed = 0.0;
result.nol_80pct_limitation = 0.0;

// Taxable income remains at $0 (cannot be negative on return)
result.taxable_income_after_nol = 0.0;
result.taxable_income = 0.0;

// Total NOL carryforward = prior years + current year
result.nol_carryforward_to_future_years =
  result.nol_carryforward_from_prior_years +
  result.nol_current_year;

// No tax liability (loss year)
result.federal_tax = 0.0;
result.refund_or_owed = result.total_payments;  // Refund all payments

// ========================================
// Foreign Tax Credit Limitation (IRC § 904)
// ========================================

// Total taxable income for FTC purposes
// Use taxable income after NOL but before FTC
result.total_taxable_income_for_ftc = result.taxable_income;

// FTC Limitation Formula:
// US Tax × (Foreign Source Income / Total Taxable Income)
//
// This ensures credit doesn't exceed US tax that would be owed
// on the foreign income if earned domestically

if (result.total_taxable_income_for_ftc > 0) {
  double foreign_income_ratio =
    result.foreign_source_income / result.total_taxable_income_for_ftc;

  result.foreign_tax_credit_limitation =
    result.federal_tax * foreign_income_ratio;
} else {
  result.foreign_tax_credit_limitation = 0.0;
}

// ========================================
// FTC Allowed (Lesser of Taxes Paid or Limitation)
// ========================================

// Current year FTC = lesser of:
// 1. Foreign taxes actually paid
// 2. FTC limitation (US tax on foreign income)
double current_year_ftc = Math.min(
  result.foreign_taxes_paid,
  result.foreign_tax_credit_limitation
);

// Add carryforward from prior years (within 10-year window)
double total_ftc_available =
  current_year_ftc + result.foreign_tax_credit_carryforward;

// FTC allowed cannot exceed limitation
result.foreign_tax_credit_allowed = Math.min(
  total_ftc_available,
  result.foreign_tax_credit_limitation
);

// ========================================
// Excess FTC (Carryback/Carryforward)
// ========================================

// If foreign taxes paid > limitation, excess carries over
double current_year_excess =
  result.foreign_taxes_paid - result.foreign_tax_credit_limitation;

if (current_year_excess > 0) {
  // Excess can be carried back 1 year or forward 10 years
  // For simplicity, we track carryforward only (carryback requires prior year data)
  result.excess_foreign_tax_credit = current_year_excess;
} else {
  result.excess_foreign_tax_credit = 0.0;
}

// Update carryforward for next year
// = Prior carryforward - amount used this year + new excess
double carryforward_used =
  result.foreign_tax_credit_allowed - current_year_ftc;

result.foreign_tax_credit_carryforward =
  Math.max(0.0, result.foreign_tax_credit_carryforward - carryforward_used) +
  result.excess_foreign_tax_credit;

// ========================================
// Update Federal Tax (after FTC)
// ========================================

// FTC is a direct credit against federal tax
// Reduces tax dollar-for-dollar (unlike deductions)
result.federal_tax =
  Math.max(0.0, result.federal_tax - result.foreign_tax_credit_allowed);

// Can use carryforward even if no current year foreign taxes

result.total_taxable_income_for_ftc = result.taxable_income;

if (result.total_taxable_income_for_ftc > 0) {
  double foreign_income_ratio =
    result.foreign_source_income / result.total_taxable_income_for_ftc;

  result.foreign_tax_credit_limitation =
    result.federal_tax * foreign_income_ratio;
} else {
  result.foreign_tax_credit_limitation = 0.0;
}

// Use carryforward up to limitation
result.foreign_tax_credit_allowed = Math.min(
  result.foreign_tax_credit_carryforward,
  result.foreign_tax_credit_limitation
);

// Update carryforward
result.foreign_tax_credit_carryforward =
  result.foreign_tax_credit_carryforward - result.foreign_tax_credit_allowed;

// Apply credit
result.federal_tax =
  Math.max(0.0, result.federal_tax - result.foreign_tax_credit_allowed);

// No foreign income = no FTC
result.foreign_tax_credit_limitation = 0.0;
result.foreign_tax_credit_allowed = 0.0;
result.excess_foreign_tax_credit = 0.0;

// Carryforward remains for future years
// (will expire after 10 years if never used)
